def segdist(P,A,B):
    dr=B[0]-A[0]; dc=B[1]-A[1]
    t=max(0,min(1,(P[0]-A[0])*dr+(P[1]-A[1])*dc)/(dr**2+dc**2))
    X,Y=A[0]+t*dr,A[1]+t*dc
    return abs(X-P[0]),abs(Y-P[1])
